BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷289·乾祐三年·长沙陷落", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4036ee803f0476e08112a5a3782bf4ceb782f41e/content/books/zizhi-tongjian/vol-289/year-0950/part-12/sources/library/tongjian-289-950-changsha-falls/source.txt", "note": "《资治通鉴》卷289·乾祐三年·长沙陷落，段落 zizhi-tongjian-a63549944a71-p003438；已核上下文及传主，纸本及异文待核。", "id": "35483223-3b8c-527d-a72c-b5334fe9ea77"}, {"title": "资治通鉴·卷289·乾祐三年·楚王更替与迎嗣", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4036ee803f0476e08112a5a3782bf4ceb782f41e/content/books/zizhi-tongjian/vol-289/year-0950/part-12/sources/library/tongjian-289-950-chu-yun-north/source.txt", "note": "《资治通鉴》卷289·乾祐三年·楚王更替与迎嗣，段落 zizhi-tongjian-a63549944a71-p003439；已核上下文及传主，纸本及异文待核。", "id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"title": "新五代史·卷18·刘赟传·留守徐州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4036ee803f0476e08112a5a3782bf4ceb782f41e/content/books/zizhi-tongjian/vol-289/year-0950/part-12/sources/library/xinwudaishi-018-xuzhou-garrison/source.txt", "note": "《新五代史》卷18·刘赟传·留守徐州，段落 xin-wudaishi-b08f244b9241-p000629；已核上下文及传主，纸本及异文待核。", "id": "0d9cf9bc-1a70-59b6-b48e-9133d63a71c9"}, {"title": "新五代史·卷66·楚世家·马希广被杀", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4036ee803f0476e08112a5a3782bf4ceb782f41e/content/books/zizhi-tongjian/vol-289/year-0950/part-12/sources/library/xinwudaishi-066-ma-xiguang-death/source.txt", "note": "《新五代史》卷66·楚世家·马希广被杀，段落 xin-wudaishi-b08f244b9241-p003331；已核上下文及传主，纸本及异文待核。", "id": "809b477a-0ac9-59eb-a7b9-9d8ee773b544"}, {"title": "旧五代史·卷103·隐帝本纪·十二月北征与任命", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b7c52ba6cde22f73d5e0bc2ffea0ec77f628d107/content/books/zizhi-tongjian/vol-289/year-0950/part-11/sources/library/jiuwudaishi-103-december-expedition/source.txt", "note": "《旧五代史》卷103·隐帝本纪·十二月北征与任命，段落 jiu-wudaishi-205deb4a7860-p002502；已核上下文及传主，纸本及异文待核。", "id": "58b01b09-5220-5d32-93ca-6bbb7fcb25bb"}, {"title": "新五代史·卷66·楚世家·彭师暠作战建议", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b7c52ba6cde22f73d5e0bc2ffea0ec77f628d107/content/books/zizhi-tongjian/vol-289/year-0950/part-11/sources/library/xinwudaishi-066-peng-plan/source.txt", "note": "《新五代史》卷66·楚世家·彭师暠作战建议，段落 xin-wudaishi-b08f244b9241-p003330；已核上下文及传主，纸本及异文待核。", "id": "34ae526f-1c32-5c88-a412-f5ce023299fe"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "韩礼", "aliases": ["韓禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国步军指挥使。950年受马希广命率二千人屯杨柳桥，控制栅路。生卒年未载。", "biography": null, "status": "draft", "id": "799d21e2-08dc-5e45-91db-a2e99190ac80"}, {"name": "雷晖", "aliases": ["雷暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人。950年穿潭州士兵衣服潜入韩礼营寨，挥剑攻击未中，却引起军中骚乱，何敬真乘乱进攻。生卒年未载。", "biography": null, "status": "draft", "id": "ee444ce5-6b64-5ea0-a90d-3a35324a55b2"}, {"name": "吴宏", "aliases": ["吳宏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国步军指挥使。950年长沙被围时出清泰门作战，城陷后向马希萼表示愿死，马希萼没有杀他。生卒年未载。", "biography": null, "status": "draft", "id": "66b3c915-508b-5a74-9792-b16c6eabefce"}, {"name": "杨涤", "aliases": ["楊滌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国小门使。947年马希范死后，与刘彦瑫等主张拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "011927f9-e8f2-562a-8e15-b5e9ccc7d716"}, {"name": "许可琼", "aliases": ["許可瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "许德勋的儿子，楚国水军指挥使。950年受马希广命率五百艘战舰屯城北津，水军接连南津，由马希崇监军。生卒年未载。", "biography": null, "status": "draft", "id": "31ee592e-a1c4-52e7-8bf7-298a4985dab9"}, {"name": "刘彦瑫", "aliases": ["劉彥瑫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国长直都指挥使。947年与李弘皋等主张拥立马希广，五月乙未称马希范遗命，拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "56a833a2-40b7-516a-baac-d3f00b328727"}, {"name": "彭师暠", "aliases": ["彭師暠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭士愁的儿子。940年受父亲派遣，率诸酋长向楚交出溪、锦、奖三州官印，请求归降。生卒年未载。", "biography": null, "status": "draft", "id": "9a01204b-6429-53ed-8ca1-76b3143bd4d8"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "李彦温", "aliases": ["李彥溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国马军指挥使。950年受马希广命率骑兵屯驼口，控制湘阴道路。生卒年未载。", "biography": null, "status": "draft", "id": "cda9474d-98db-5701-940a-efb99682aaa1"}, {"name": "张晖（马希广将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的马军指挥使。950年从另一条路线攻朗州，得知刘彦瑫战败后驻益阳；遭进攻时骗部下留城，自己逃回长沙。与博州守将、后晋使者等同名人物尚无同人证据，分开建档。生卒年未载。", "biography": null, "status": "draft", "id": "01326810-19e9-5e02-8181-27a823949592"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "李弘皋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。生卒年未载。", "biography": null, "status": "draft", "id": "87806f3c-0c40-510b-b333-2e0b18bc54da"}, {"name": "李弘节", "aliases": ["李弘節"], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "楚国掌书记李弘皋的弟弟。950年长沙陷落后被马希萼一方捕获囚禁，随后与李弘皋等遭残酷杀害。生年未载。", "biography": null, "status": "draft", "id": "64a0ce84-ae28-5859-a520-9242f8d1b759"}, {"name": "唐昭胤", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "楚国都军判官。950年长沙陷落后被马希萼一方捕获囚禁，随后与李弘皋等遭残酷杀害。生年未载。", "biography": null, "status": "draft", "id": "c257d447-a3dd-5e15-9319-fd3ac39feef9"}, {"name": "邓懿文", "aliases": ["鄧懿文"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国营田使，受马希范命登记逃亡民户留下的田地，招募民众耕种缴租。具体任职与行动年月未载。", "biography": null, "status": "draft", "id": "a5089609-5c2a-5e38-90e1-c6c7ab18b843"}, {"name": "刘宾", "aliases": ["劉賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国内外巡检侍卫指挥使。950年十二月丙午，奉马希萼命禁止长沙的焚烧与劫掠。与同名人物尚无同人证据，生卒年未载。", "biography": null, "status": "draft", "id": "f1dda8d7-6fa5-56a6-8e15-c9a0bec4cecd"}, {"name": "朱进忠", "aliases": ["硃进忠", "朱進忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的指挥使。950年率兵三千攻益阳，随后建议马希萼亲自率军攻潭州。电子底本也写硃进忠，统一简体姓名，原文保留。生卒年未载。", "biography": null, "status": "draft", "id": "0ba585e1-d1aa-5ce5-ad37-d02d89127713"}, {"name": "刘赟", "aliases": ["劉赟", "劉贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的儿子，刘知远喜爱他，把他当作自己的儿子。《新五代史》记948年任徐州节度使，949年《通鉴》记以武宁节度使身份获加同平章事。后续经历随主书年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "8b95e2f2-9627-55f8-adca-a0b287179971"}, {"name": "巩延美", "aliases": ["鞏延美", "巩庭美", "鞏庭美", "巩廷美", "鞏廷美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的右都押牙。950年刘赟离开徐州西行迎立时，与杨温留守徐州。《新五代史》刘赟传写作巩庭美，同职同伴及同一留守场景对应；生卒年本批未录。", "biography": null, "status": "draft", "id": "4df9296b-060c-55ce-9ca5-a4523a55428f"}, {"name": "杨温", "aliases": ["楊溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的元从都教练使。950年刘赟离开徐州西行迎立时，与巩延美留守徐州。生卒年本批未录。", "biography": null, "status": "draft", "id": "899b9466-92c5-5e46-b835-0d2e7cfdbf64"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "马光赞", "aliases": ["馬光贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的儿子。950年十一月，马希萼率军向长沙进发，留下他守朗州。生卒年和母亲身份未载。", "biography": null, "status": "draft", "id": "3fbbf096-7e41-591f-8fb9-2c5b3cb24eb3"}, {"name": "拓跋恒", "aliases": ["元恒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：拓跋恒，楚国仆射获任者。", "biography": null, "status": "draft", "id": "a53a8f9a-f7db-5e25-b74c-4b81973658e7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "何敬真率三千部族兵在杨柳桥列阵", "start_year": 950, "end_year": 950, "time_original": "950年十二月甲辰", "dynasty": "五代十国", "description": "何敬真率三千部族兵在杨柳桥列阵。", "phases": [], "location_name": "杨柳桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f6a16ea1-fb5d-5259-9343-cb48038695c5"}, {"title": "何敬真看到韩礼营中旌旗混乱，认为容易击败", "start_year": 950, "end_year": 950, "time_original": "950年十二月甲辰", "dynasty": "五代十国", "description": "何敬真看到韩礼营中旌旗混乱，认为容易击败。", "phases": [], "location_name": "杨柳桥韩礼营寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "de82dee9-2170-5ea3-be17-4ff02f213625"}, {"title": "雷晖伪装潭州士兵潜入韩礼营寨，袭击未中", "start_year": 950, "end_year": 950, "time_original": "950年十二月甲辰", "dynasty": "五代十国", "description": "雷晖伪装潭州士兵潜入韩礼营寨，袭击未中。", "phases": [], "location_name": "韩礼营寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a90daa23-85a3-5e18-93d3-1f33f2dd1321"}, {"title": "何敬真乘乱击溃韩礼所部，韩礼伤后回家去世", "start_year": 950, "end_year": 950, "time_original": "950年十二月甲辰交战，韩礼回家去世确日未单列", "dynasty": "五代十国", "description": "何敬真乘乱击溃韩礼所部，韩礼伤后回家去世。", "phases": [], "location_name": "杨柳桥及韩礼家中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "03d3fd84-7021-5d10-a061-89bd0e2fd451"}, {"title": "朗州军从水陆两路急攻长沙", "start_year": 950, "end_year": 950, "time_original": "950年十二月甲辰韩礼败后", 